package dao;
import config.ConexionBD;import java.sql.*;import java.util.*;import negocio.*;
public class OrdenPagoDAOMySQL implements OrdenPagoDAO {
 public OrdenPago guardar(OrdenPago o){OrdenPago existente=buscarPorIdempotencia(o.getClaveIdempotencia());if(existente!=null)return existente;String q="INSERT INTO ordenes_pago(reserva_id,proveedor,metodo,estado,importe,moneda,clave_idempotencia,referencia_externa,preferencia_externa_id,pago_externo_id,url_pago,fecha_expiracion,fecha_aprobacion) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){param(s,o);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())o.setId(r.getLong(1));}return buscar(o.getId());}catch(SQLException e){if(esDuplicado(e)){OrdenPago x=buscarPorIdempotencia(o.getClaveIdempotencia());if(x!=null)return x;}throw new RuntimeException("No se pudo guardar la orden de pago.",e);}}
 private void param(PreparedStatement s,OrdenPago o)throws SQLException{s.setLong(1,o.getReservaId());s.setString(2,o.getProveedor().name());s.setString(3,o.getMetodo().name());s.setString(4,o.getEstado().name());s.setBigDecimal(5,o.getImporte());s.setString(6,o.getMoneda());s.setString(7,o.getClaveIdempotencia());nullable(s,8,o.getReferenciaExterna());nullable(s,9,o.getPreferenciaExternaId());nullable(s,10,o.getPagoExternoId());nullable(s,11,o.getUrlPago());fecha(s,12,o.getFechaExpiracion());fecha(s,13,o.getFechaAprobacion());}
 public OrdenPago buscar(long id){return uno("SELECT * FROM ordenes_pago WHERE id=?",id);}
 public OrdenPago buscarPorIdempotencia(String k){return texto("SELECT * FROM ordenes_pago WHERE clave_idempotencia=?",k);}
 public OrdenPago buscarPorReferencia(ProveedorPago p,String r){if(p==null||r==null||r.isBlank())return null;String q="SELECT * FROM ordenes_pago WHERE proveedor=? AND referencia_externa=?";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,p.name());s.setString(2,r);try(ResultSet x=s.executeQuery()){return x.next()?map(x):null;}}catch(SQLException e){throw new RuntimeException("No se pudo buscar la orden externa.",e);}}
 public OrdenPago buscarPorPagoExterno(ProveedorPago p,String id){if(p==null||id==null||id.isBlank())return null;String q="SELECT * FROM ordenes_pago WHERE proveedor=? AND pago_externo_id=?";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,p.name());s.setString(2,id);try(ResultSet r=s.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw new RuntimeException("No se pudo buscar el pago externo.",e);}}
 public boolean asociarPagoExterno(long id,String pagoId){if(id<=0||pagoId==null||pagoId.isBlank())throw new IllegalArgumentException("La orden y el pago externo son obligatorios.");try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement("UPDATE ordenes_pago SET pago_externo_id=COALESCE(pago_externo_id,?) WHERE id=? AND proveedor='MERCADO_PAGO' AND (pago_externo_id IS NULL OR pago_externo_id=?)")){s.setString(1,pagoId);s.setLong(2,id);s.setString(3,pagoId);return s.executeUpdate()==1;}catch(SQLException e){throw new RuntimeException("No se pudo asociar el pago externo.",e);}}
 public List<OrdenPago> listarPorReserva(long id){List<OrdenPago> out=new ArrayList<>();String q="SELECT * FROM ordenes_pago WHERE reserva_id=? ORDER BY fecha_creacion DESC,id DESC";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){while(r.next())out.add(map(r));}return out;}catch(SQLException e){throw new RuntimeException("No se pudieron listar las órdenes.",e);}}
 public boolean actualizarEstado(long id,long v,EstadoOrdenPago e,String ref){String q="UPDATE ordenes_pago SET estado=?,referencia_externa=COALESCE(?,referencia_externa),fecha_aprobacion=CASE WHEN ?='APROBADA' THEN COALESCE(fecha_aprobacion,CURRENT_TIMESTAMP) ELSE fecha_aprobacion END,version=version+1 WHERE id=? AND version=?";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,e.name());nullable(s,2,ref);s.setString(3,e.name());s.setLong(4,id);s.setLong(5,v);return s.executeUpdate()==1;}catch(SQLException x){throw new RuntimeException("No se pudo actualizar la orden.",x);}}
 public boolean completarCheckout(long id,long version,String preferencia,String url){if(id<=0||preferencia==null||preferencia.isBlank()||url==null||url.isBlank())throw new IllegalArgumentException("La orden, preferencia y URL son obligatorias.");String q="UPDATE ordenes_pago SET preferencia_externa_id=?,url_pago=?,estado='ESPERANDO_PAGO',version=version+1 WHERE id=? AND version=? AND estado IN ('CREADA','ERROR')";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,preferencia);s.setString(2,url);s.setLong(3,id);s.setLong(4,version);return s.executeUpdate()==1;}catch(SQLException e){throw new RuntimeException("No se pudo completar el checkout de la orden.",e);}}
 private OrdenPago uno(String q,long id){try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw new RuntimeException("No se pudo buscar la orden.",e);}}private OrdenPago texto(String q,String v){if(v==null||v.isBlank())return null;try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,v);try(ResultSet r=s.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw new RuntimeException("No se pudo buscar la orden.",e);}}
 private OrdenPago map(ResultSet r)throws SQLException{OrdenPago o=new OrdenPago();o.setId(r.getLong("id"));o.setReservaId(r.getLong("reserva_id"));o.setProveedor(ProveedorPago.valueOf(r.getString("proveedor")));o.setMetodo(MetodoOrdenPago.valueOf(r.getString("metodo")));o.setEstado(EstadoOrdenPago.valueOf(r.getString("estado")));o.setImporte(r.getBigDecimal("importe"));o.setMoneda(r.getString("moneda"));o.setClaveIdempotencia(r.getString("clave_idempotencia"));o.setReferenciaExterna(r.getString("referencia_externa"));o.setPreferenciaExternaId(r.getString("preferencia_externa_id"));o.setPagoExternoId(r.getString("pago_externo_id"));o.setUrlPago(r.getString("url_pago"));o.setVersion(r.getLong("version"));o.setFechaExpiracion(t(r,"fecha_expiracion"));o.setFechaAprobacion(t(r,"fecha_aprobacion"));o.setFechaCreacion(t(r,"fecha_creacion"));o.setFechaActualizacion(t(r,"fecha_actualizacion"));return o;}private java.time.LocalDateTime t(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toLocalDateTime();}private void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null||v.isBlank())s.setNull(i,Types.VARCHAR);else s.setString(i,v);}private void fecha(PreparedStatement s,int i,java.time.LocalDateTime v)throws SQLException{if(v==null)s.setNull(i,Types.TIMESTAMP);else s.setTimestamp(i,Timestamp.valueOf(v));}private boolean esDuplicado(SQLException e){return "23000".equals(e.getSQLState())||e.getErrorCode()==1062;}
}
